# --- Hand-written: make the stock ledger append-only on PostgreSQL ----------
# Corrections must be posted as new ADJUSTMENT movements, never by editing history.
def _create_ledger_guard() -> None:
    if op.get_bind().dialect.name != "postgresql":
        return
    op.execute(
        """
        CREATE OR REPLACE FUNCTION stock_movements_block_change() RETURNS trigger AS $$
        BEGIN
            RAISE EXCEPTION 'stock_movements is append-only; post a reversing ADJUSTMENT instead';
        END;
        $$ LANGUAGE plpgsql;
        """
    )
    op.execute(
        """
        CREATE TRIGGER trg_stock_movements_append_only
        BEFORE UPDATE OR DELETE ON stock_movements
        FOR EACH ROW EXECUTE FUNCTION stock_movements_block_change();
        """
    )


def _drop_ledger_guard() -> None:
    if op.get_bind().dialect.name != "postgresql":
        return
    op.execute("DROP TRIGGER IF EXISTS trg_stock_movements_append_only ON stock_movements")
    op.execute("DROP FUNCTION IF EXISTS stock_movements_block_change()")
